<script setup lang="ts">
import { computed, ref } from 'vue'
import AppIcon from '@/components/AppIcon.vue'
import PodcastCard from '@/components/PodcastCard.vue'
import PodcastDetail from '@/components/PodcastDetail.vue'
import EpisodeList from '@/components/EpisodeList.vue'
import { useOfficialStore } from '@/stores/official'
import { useAccountStore } from '@/stores/account'
const official = useOfficialStore(), account = useAccountStore()
const input = ref(official.searchKeyword), selected = ref('')
const selectedPodcast = computed(() => official.searchPodcasts.find(p => p.pid === selected.value))
async function search(word = input.value): Promise<void> { input.value = word; selected.value = ''; await official.runSearch(word, official.searchType) }
async function setType(type: 'PODCAST' | 'ALL'): Promise<void> { official.searchType = type; if (input.value.trim()) await search() }
async function open(pid: string): Promise<void> { selected.value = selected.value === pid ? '' : pid; if (selected.value) await official.loadEpisodes(pid) }
</script>
<template><section class="page"><header class="page-heading"><div><span class="eyebrow">FIND YOUR NEXT FAVORITE</span><h1>寻找，心动的声音<span class="accent">.</span></h1><p>输入一个关键词，让好奇心带路。</p></div></header><form class="search-form" @submit.prevent="search()"><AppIcon name="search" :size="23" /><input v-model="input" type="search" aria-label="搜索播客或单集" placeholder="搜索播客、单集或你感兴趣的话题" maxlength="200" /><button class="button primary" :disabled="!input.trim() || official.searchStatus === 'loading' || !account.isLoggedIn">{{ official.searchStatus === 'loading' ? '搜索中…' : '搜索' }}</button></form><div v-if="!account.isLoggedIn" class="notice"><AppIcon name="info" :size="18" /><span>搜索需要连接你的小宇宙账号。</span><RouterLink to="/official" class="text-button">去登录<AppIcon name="arrow" :size="15" /></RouterLink></div><template v-else><div class="category-tabs"><button :class="{ active: official.searchType === 'PODCAST' }" @click="setType('PODCAST')">播客</button><button :class="{ active: official.searchType === 'ALL' }" @click="setType('ALL')">全部内容</button><span v-if="official.searchStatus === 'ready'" class="result-count">{{ official.searchPodcasts.length + official.searchEpisodes.length }} 条结果</span></div><p v-if="official.searchStatus === 'loading'" class="loading-message" role="status">正在搜索「{{ official.searchKeyword }}」…</p><p v-else-if="official.searchStatus === 'error'" class="notice error" role="alert">{{ official.searchError }}</p><div v-else-if="official.searchStatus === 'empty'" class="empty-state"><AppIcon name="search" :size="38" /><h2>还没找到这个声音</h2><p>试试更简短的关键词，或者换一个话题。</p></div><div v-if="official.searchPodcasts.length" class="podcast-grid"><PodcastCard v-for="podcast in official.searchPodcasts" :key="podcast.pid" :podcast="podcast" :active="selected === podcast.pid" @open="open" /></div><PodcastDetail v-if="selectedPodcast" :podcast="selectedPodcast" @close="selected = ''" /><section v-if="official.searchEpisodes.length" class="section-block"><h2 class="section-title">相关单集</h2><EpisodeList :items="official.searchEpisodes" /></section></template><div v-if="official.searchStatus === 'idle' || !account.isLoggedIn" class="search-suggestions"><span class="eyebrow">A FEW IDEAS TO START</span><h2>此刻，对什么好奇？</h2><div class="suggestion-chips"><button v-for="word in ['科技与未来', '生活方式', '商业观察', '故事', '读书', '电影']" :key="word" :disabled="!account.isLoggedIn" @click="search(word)">{{ word }}<AppIcon name="arrow" :size="14" /></button></div><p class="muted">{{ account.isLoggedIn ? '从一个小问题，开启一段新旅程。' : '连接账号后，点击话题即可开始搜索。' }}</p></div></section></template>
